    console.assert(JSON.stringify(candidate([1000000, 2000000, 3000000, 4000000, 5000000, 6000000])) === JSON.stringify(-1));
    console.assert(JSON.stringify(candidate([210, 330, 55, 14, 22, 110])) === JSON.stringify(-1));
}
